var e={imageWidth:1e3,imageHeight:1250},t=[{slug:`rose`,name:`玫瑰`,english:`Rose`,latin:`Rosa spp.`,image:`/images/flowers/rose.jpg`,imageAlt:`浅米白背景前的红玫瑰花束`,...e,family:`主花`,season:`全年供应，5–10 月香气与开放度更好`,colors:`红、粉、白、香槟、紫，以及各种喷色`,price:`8–15 元/支（昆明普通等级）`,vaseLife:`5–7 天`,scent:`淡，凑近才能闻清`,meaning:`最常见的解读是热烈而确定的爱；颜色不同说法略有差别，红玫瑰最直接，香槟色更偏“珍视”。`,summary:`花店里最稳的主花：认知度高、色系全、几乎不挑包装。缺点是节日溢价明显，瓣层多的品种也更容易“垂头”。`,bestFor:[`第一次送花，不想在花语上出错`,`需要一眼有分量的主花束`,`纪念日、求婚、周年`],notFor:[`想要清淡低饱和的桌花`,`预算很紧又想显得别致`,`对香气比较敏感`],buyTips:[`看最外层两片“保护瓣”：边缘轻微发干正常，大面积发黑发软说明放久了。`,`轻捏花头基部，硬挺说明新鲜；发软、晃动说明已经脱水。`,`枝条切口应是浅绿的新鲜断面，发褐发黑不要。`,`同价位选花苞略开、瓣层多的，回家还能再开两天。`],care:[`45° 斜剪 2–3 cm，去掉所有会浸在水里的叶片。`,`水位约花瓶的 1/3，每两天换水并重新剪一次。`,`避免空调直吹和阳光直晒，花瓣容易失水卷边。`,`出现垂头时，用报纸把花头卷紧、深水泡 2 小时，多数能救回来。`],combos:[`eucalyptus`,`baby-breath`,`eustoma`],occasions:[`confession`,`birthday`,`wedding`,`festival`],tags:[`主花`,`全年供应`,`认知度高`],updated:`2026-11-22`,featured:!0},{slug:`eustoma`,name:`洋桔梗`,english:`Eustoma`,latin:`Eustoma grandiflorum`,image:`/images/flowers/eustoma.jpg`,imageAlt:`浅米白背景前的淡紫色洋桔梗`,...e,family:`主花`,season:`全年供应，4–6 月与 9–11 月状态最好`,colors:`白、粉、香槟、淡紫、复色`,price:`10–20 元/支`,vaseLife:`7–10 天`,scent:`几乎没有气味`,meaning:`真诚不变的爱、无邪与温柔，是近年花束里最常用的“柔和系”花语。`,summary:`花瓣轻薄，层层叠叠像纸折出来的花，比玫瑰更柔。价格适中、耐放，既能当主花，也常被用来替代昂贵的玫瑰。`,bestFor:[`日常花束和桌花`,`低饱和、温柔色系`,`送长辈、同事不容易出错`],notFor:[`需要强烈仪式感的大花束`,`追求浓郁香气`,`需要硬挺造型线条`],buyTips:[`选已经有 2–3 朵半开的，花苞太紧可能一直不开。`,`花瓣边缘不能发褐、发黏，那是放久或受潮的表现。`,`花茎要绿、有韧性，发软说明脱水。`,`叶片不要有黄斑，洋桔梗的叶斑很容易扩散。`],care:[`浅水养护，水位 5–8 cm 即可，水多容易烂茎。`,`每两天换水，顺手把瓶壁的黏液洗干净。`,`去掉水下叶片，避免泡水后发臭。`,`放在散射光处，避开热源，能让花期更整齐。`],combos:[`rose`,`baby-breath`,`eucalyptus`],occasions:[`birthday`,`visit`,`business`,`wedding`],tags:[`主花`,`耐放`,`温柔色系`],updated:`2026-11-22`,featured:!0},{slug:`tulip`,name:`郁金香`,english:`Tulip`,latin:`Tulipa gesneriana`,image:`/images/flowers/tulip.jpg`,imageAlt:`浅灰白背景前的粉白郁金香花束`,...e,family:`主花`,season:`12–4 月为主，进口花全年可见`,colors:`红、粉、黄、白、橙、紫`,price:`8–15 元/支`,vaseLife:`5–7 天`,scent:`淡，靠近有一点青草气`,meaning:`爱的告白、体贴与祝福；颜色不同略有差别，黄色更偏明朗，粉色更偏温柔。`,summary:`线条感强，一把同色就很好看。买回家后花茎还会继续长高 1–2 cm，并向外弯，这是正常现象，用浅水和直筒瓶更好看。`,bestFor:[`单色一束的极简花束`,`春日感、轻盈的礼物`,`桌面小瓶花`],notFor:[`需要蓬松大花束`,`夏季高温环境`,`想要两周以上的观赏期`],buyTips:[`完全闭合、硬得像蜡的花苞可能不开，选刚露色的。`,`花瓣饱满、颜色均匀，花茎硬挺不弯。`,`叶片要直立有光泽，发黄卷曲说明放久了。`,`球茎类怕压，别选花头被包装挤变形的。`],care:[`浅水，水位 5 cm 左右，水多容易烂茎。`,`每两天换水，换水时重新剪一刀。`,`避开阳光直射和暖风口，光热会让它开得太快。`,`花头下垂时，可在花头下方茎上轻扎一针透气，再深水养一晚。`],combos:[`eucalyptus`,`ranunculus`,`eustoma`],occasions:[`confession`,`birthday`,`festival`],tags:[`主花`,`春季`,`线条感`],updated:`2026-11-22`,featured:!0},{slug:`sunflower`,name:`向日葵`,english:`Sunflower`,latin:`Helianthus annuus`,image:`/images/flowers/sunflower.jpg`,imageAlt:`窗边玻璃瓶中的金黄色向日葵`,...e,family:`主花`,season:`6–10 月本地花最好，其余季节多为温室或进口`,colors:`金黄、柠檬黄`,price:`12–20 元/支`,vaseLife:`5–7 天`,scent:`淡，茎叶有明显的青味`,meaning:`阳光、信念、沉默而坚定的支持，很适合用来“给人打气”。`,summary:`一朵就能撑起整束花，毕业、开业、庆祝都好用。但花头重、容易低头，挑茎粗硬、花心还没完全展开的会更耐久。`,bestFor:[`毕业、升学、比赛加油`,`开业与乔迁`,`教师节、谢师`],notFor:[`精致浪漫的小花束`,`小花瓶桌花（花头比例太大）`,`需要轻便易带走的场合`],buyTips:[`花心中央的管状花还没完全展开的更耐久。`,`花瓣完整、颜色饱和，边缘不发黑。`,`花茎越粗越好，细茎撑不住花头。`,`叶片大而绿，发蔫说明缺水。`],care:[`向日葵喝水多，水位可以到花瓶的 1/3–1/2。`,`每天换水，瓶口以下的叶子全部去掉。`,`花头太重时，用一根细枝或竹签做支撑。`,`放在明亮但不直晒的位置，避免花头快速低垂。`],combos:[`eucalyptus`,`baby-breath`,`daisy`],occasions:[`birthday`,`business`,`festival`],tags:[`主花`,`夏季`,`打气`],updated:`2026-11-22`,featured:!0},{slug:`hydrangea`,name:`绣球`,english:`Hydrangea`,latin:`Hydrangea macrophylla`,image:`/images/flowers/hydrangea.jpg`,imageAlt:`浅米白背景前的蓝紫色绣球花`,...e,family:`主花`,season:`5–9 月为主，进口花在其他月份也能买到`,colors:`蓝、紫、粉、白、绿`,price:`25–45 元/支`,vaseLife:`3–5 天`,scent:`淡`,meaning:`希望、美满、团圆，也有“见花如面”的温柔说法。`,summary:`一支就顶半个花束，很适合做主视觉，婚礼、前台、拍照都出片。但它最怕脱水，状态不好时半天就蔫，必须深水勤补水。`,bestFor:[`单支大花束的主视觉`,`婚礼与拍照`,`前台、客厅的大瓶花`],notFor:[`需要摆放三天以上`,`干燥、空调直吹的环境`,`需要长途配送`],buyTips:[`花瓣挺括、没有压痕，花头拿起来有分量。`,`边缘发褐、花头轻飘的已经脱水，不要。`,`茎切口要新鲜，绣球的茎很容易发黑。`,`买的时候轻摇一下，掉瓣多的不要。`],care:[`深水养护，水位到花瓶的 2/3。`,`每天换水，可轻喷水雾在花头上。`,`蔫了可整枝（含花头）浸入清水 1 小时急救。`,`远离空调出风口和热源，绣球失水极快。`],combos:[`rose`,`eucalyptus`,`baby-breath`],occasions:[`wedding`,`business`,`birthday`],tags:[`主花`,`夏季`,`怕脱水`],updated:`2026-11-22`},{slug:`lily`,name:`百合`,english:`Lily`,latin:`Lilium spp.`,image:`/images/flowers/lily.jpg`,imageAlt:`浅灰白背景前的白色百合`,...e,family:`主花`,season:`全年供应，5–8 月本地花状态最好`,colors:`白、粉、黄`,price:`15–25 元/支（通常一枝多朵）`,vaseLife:`7–10 天`,scent:`浓，香味扩散明显`,meaning:`百年好合、纯洁、顺遂，是婚礼和长辈场合的传统花材。`,summary:`一支多朵、开花有先后，观赏期长。香气浓，适合客厅，不适合小卧室和探病。开花后最好摘掉花药，否则花粉会把花瓣和桌布染色。`,bestFor:[`家居客厅的大瓶花`,`长辈、乔迁、婚礼`,`需要长期观赏`],notFor:[`探病与病房`,`密闭小房间`,`家里有猫（百合对猫有毒性）`],buyTips:[`选有 2–3 朵已开、其余花苞饱满的，回家能陆续开。`,`花苞发软、发黄或已经裂开的不要。`,`叶片翠绿、茎硬挺，切口不发黑。`,`香味过冲的通常已经开久了，别选。`],care:[`开花后摘掉花药，防止花粉染色。`,`水位约花瓶的 1/3，每两天换水。`,`去掉水下叶片，避免泡水发臭。`,`家里有猫时不要摆放，百合对猫有明确毒性。`],combos:[`rose`,`eustoma`,`eucalyptus`],occasions:[`wedding`,`birthday`,`business`],tags:[`主花`,`浓香`,`对猫有毒`],updated:`2026-11-22`},{slug:`carnation`,name:`康乃馨`,english:`Carnation`,latin:`Dianthus caryophyllus`,image:`/images/flowers/carnation.jpg`,imageAlt:`浅米白背景前的粉色康乃馨`,...e,family:`主花`,season:`全年供应`,colors:`粉、红、白、紫、复色`,price:`5–10 元/支`,vaseLife:`10–14 天`,scent:`淡`,meaning:`母爱、感恩、尊敬与健康，母亲节和教师节的主力花材。`,summary:`最耐放的常见花材，养得好能开两周。花头在运输中容易压伤，挑的时候重点看花瓣边缘是否完整。`,bestFor:[`母亲节、教师节`,`送长辈`,`需要摆放很久的场合`],notFor:[`追求高级极简风`,`婚礼主花`,`需要轻盈蓬松的造型`],buyTips:[`花瓣紧实、边缘不发褐，花头与茎连接处硬。`,`花苞半开最好，全开的已经开始老化。`,`茎要粗绿，细软的多是次级货。`,`包装里被压变形的花头不要，回家也展不开。`],care:[`水位约花瓶的 1/3，斜剪后插入。`,`每 3 天换水，康乃馨对水质不算敏感但也要干净。`,`远离水果，水果释放的乙烯会加速花朵老化。`,`花瓣轻微外翻是正常的开放过程，不算坏。`],combos:[`baby-breath`,`eucalyptus`,`rose`],occasions:[`festival`,`visit`,`birthday`,`business`],tags:[`主花`,`超耐放`,`送长辈`],updated:`2026-11-22`},{slug:`peony`,name:`芍药`,english:`Peony`,latin:`Paeonia lactiflora`,image:`/images/flowers/peony.jpg`,imageAlt:`浅米白背景前的浅粉色芍药`,...e,family:`主花`,season:`4–6 月，花期很短`,colors:`粉、白、珊瑚、紫红`,price:`25–45 元/支（季末和进口更贵）`,vaseLife:`3–5 天`,scent:`淡`,meaning:`富贵、圆满、依依不舍，也常被用来表达“舍不得”。`,summary:`季节限定，开花过程本身就是看头。买“铁头”花苞回家自己开很有意思，但必须赶在花期内；过季就只能等明年。`,bestFor:[`春夏桌花与婚礼`,`送女性长辈`,`拍照与重要纪念日`],notFor:[`需要长期摆放`,`预算有限`,`错过花期的临时需求`],buyTips:[`花苞像棉花糖、略有弹性，通常能开；硬得像石头可能不开。`,`花瓣没有褐斑，花头不沉重发软。`,`茎粗直，叶片完整。`,`季末的花苞容易“死在半开”，尽量选已露花瓣的。`],care:[`浅水养护，花瓶 1/3 即可。`,`想快点开可用温水，想慢点开就放凉爽处。`,`每天换水，花开后尽量少搬动。`,`不要往花瓣上喷水，容易留下水渍和褐斑。`],combos:[`ranunculus`,`eucalyptus`,`tulip`],occasions:[`wedding`,`birthday`,`confession`],tags:[`主花`,`季节限定`,`开花过程`],updated:`2026-11-22`},{slug:`ranunculus`,name:`洋牡丹`,english:`Ranunculus`,latin:`Ranunculus asiaticus`,image:`/images/flowers/ranunculus.jpg`,imageAlt:`浅灰白背景前的橙色洋牡丹`,...e,family:`主花`,season:`12–5 月`,colors:`橙、粉、白、黄、红`,price:`8–15 元/支`,vaseLife:`5–7 天`,scent:`几乎没有`,meaning:`受欢迎、迷人的魅力，花语偏现代，适合轻松的表达。`,summary:`花瓣一层层卷成小球，颜色饱和，是花束里最容易出彩的“副主角”。茎偏软，插瓶时需要互相支撑。`,bestFor:[`春季花束`,`婚礼与拍照`,`给花束加一抹亮色`],notFor:[`需要硬挺线条的造型`,`长途运输`,`高温环境`],buyTips:[`花苞紧实、颜色鲜明，花瓣没有压伤。`,`茎不能软塌，软茎插瓶后容易倒。`,`叶片翠绿，发黄说明放久了。`,`同色系一起买，成束效果最好。`],care:[`浅水 5–8 cm，茎软，水多容易烂。`,`换水时轻拿，避免折断花茎。`,`用瓶口较窄的花瓶帮助支撑。`,`放在凉爽处，高温会让它开得很快。`],combos:[`tulip`,`peony`,`eucalyptus`],occasions:[`wedding`,`confession`,`birthday`],tags:[`主花`,`冬季到春季`,`色彩强`],updated:`2026-11-22`},{slug:`baby-breath`,name:`满天星`,english:`Baby's breath`,latin:`Gypsophila paniculata`,image:`/images/flowers/baby-breath.jpg`,imageAlt:`浅灰白背景前的白色满天星`,...e,family:`配花`,season:`全年供应`,colors:`白、粉`,price:`15–30 元/扎`,vaseLife:`7–14 天，干插更久`,scent:`淡`,meaning:`纯洁的心、思念与守望，常作为“陪衬”的花语出现。`,summary:`最常用的配花，负责把主花“托起来”。容易掉花，插瓶后尽量少移动；也可以直接倒挂风干做干花。`,bestFor:[`填充花束、增加蓬松感`,`桌花点缀`,`做干花`],notFor:[`单独成束（容易显单薄）`,`需要精细造型的场合`],buyTips:[`小花开放均匀，不要一半已经发黄。`,`茎要绿，抖一下掉花少。`,`整扎拿起来轻、干爽，没有霉味。`,`粉色满天星注意看是否染色，染色的遇水会掉色。`],care:[`水位约花瓶的 1/3，斜剪后插入。`,`掉花是正常现象，尽量少搬动。`,`做干花时倒挂阴干 7–10 天，不要晒。`,`和主花同瓶时，注意别被主花挤到脱水。`],combos:[`rose`,`carnation`,`eustoma`],occasions:[`birthday`,`confession`,`wedding`,`festival`],tags:[`配花`,`可做干花`,`蓬松`],updated:`2026-11-22`,featured:!0},{slug:`daisy`,name:`小雏菊`,english:`Daisy`,latin:`Bellis perennis`,image:`/images/flowers/daisy.jpg`,imageAlt:`浅灰白背景前的白色小雏菊`,...e,family:`配花`,season:`3–6 月最好，全年有温室花`,colors:`白瓣黄心，也有粉、紫`,price:`8–15 元/扎`,vaseLife:`7–10 天`,scent:`淡`,meaning:`天真、希望、藏在心里的喜欢。`,summary:`便宜、耐放，一小扎就能让桌面活起来。适合日常自用和轻松的小礼物，不适合撑正式场合的大花束。`,bestFor:[`日常桌花`,`轻松的小礼物`,`田园风搭配`],notFor:[`正式商务场合`,`大型花束的主花`],buyTips:[`花心饱满、花瓣白净，没有褐边。`,`茎硬挺，弯头的不耐久。`,`叶片翠绿，发黄说明放久了。`,`一扎里开放程度接近的更好插。`],care:[`水位约花瓶的 1/3，去掉水下叶。`,`每两天换水，雏菊的茎容易泡软。`,`放在明亮散射光处，避免直晒。`,`花心发黑时剪掉那一朵，别影响其他花。`],combos:[`eucalyptus`,`baby-breath`,`sunflower`],occasions:[`birthday`,`confession`,`festival`],tags:[`配花`,`便宜耐放`,`田园感`],updated:`2026-11-22`},{slug:`eucalyptus`,name:`尤加利叶`,english:`Eucalyptus`,latin:`Eucalyptus cinerea`,image:`/images/flowers/eucalyptus.jpg`,imageAlt:`浅米白背景前的银绿色尤加利枝叶`,...e,family:`叶材`,season:`全年供应`,colors:`银绿、灰绿`,price:`10–20 元/扎`,vaseLife:`7–14 天，干插更久`,scent:`明显，清凉的草本香`,meaning:`恩赐与回忆，这层花语偏现代用法，实际搭配时不必太讲究。`,summary:`最通用的叶材，一笔就能让花束有“呼吸感”。耐放、干了也好看，很适合新手练习配花和做干花。`,bestFor:[`任何花束打底`,`干花与香氛装饰`,`北欧、极简风格`],notFor:[`需要鲜绿饱满的传统花篮`,`对气味敏感的小空间`],buyTips:[`叶片有自然的白粉感，枝条不发干、不发黑。`,`轻揉叶片有清香，没有霉味。`,`枝条有韧性，折一下不断。`,`叶片不要大面积脱落，脱落的通常放久了。`],care:[`水位约花瓶的 1/3，斜剪后插入。`,`可以直接干插，风干后颜色会变浅但形态还在。`,`叶片积灰用湿布轻擦，不要用水冲。`,`和主花同瓶时，留出空间，别把主花挤住。`],combos:[`rose`,`hydrangea`,`tulip`],occasions:[`wedding`,`business`,`birthday`],tags:[`叶材`,`超耐放`,`可做干花`],updated:`2026-11-22`,featured:!0}],n=t.filter(e=>e.featured),r=e=>t.find(t=>t.slug===e),i=e=>t.filter(t=>t.family===e);export{r as i,t as n,i as r,n as t};